/* The tables of M05 · Integrations and API. */

/** One configured connection to an outside service. */
export const integrationConnections = defineTable(
  'integration_connections',
  { module: 'M05', scope: 'org' },
  {
    ...baseColumns,
    category: enumText(integrationConnectionCategories).notNull(),
    /** `jazzcash`, `easypaisa`, `onebill`, `whatsapp_cloud`, `sms_generic`, `smtp`, `zkteco`, `traccar`, `log`, `fake` */
    provider: text().notNull(),
    /** empty means the whole group */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    name: text().notNull(),
    mode: enumText(integrationConnectionModes).notNull().default('test'),
    /** non-secret settings (merchant id, sender name) */
    config: jsonb().notNull().default({}),
    /** encrypted keys; write-only */
    secretsEncrypted: text(),
    isDefault: boolean().notNull().default(false),
    status: enumText(integrationConnectionStatuses).notNull().default('disconnected'),
    lastCheckedAt: timestamptz(),
    lastError: text(),
  },
  (t) => [
    uniqueIndex('integration_connections_default_uq')
      .on(
        t.orgId,
        t.category,
        sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(sql`${t.isDefault} and ${t.deletedAt} is null`),
  ],
);

/** Every message an outside service sends us, kept raw. */
export const webhookEvents = defineTable(
  'webhook_events',
  { module: 'M05', scope: 'platform' },
  {
    id: idColumn(),
    ...auditColumns,
    /** resolved after parsing */
    orgId: uuid().references((): AnyPgColumn => orgs.id),
    provider: text().notNull(),
    /** the provider's own id */
    eventId: text().notNull(),
    signatureOk: boolean().notNull(),
    payload: jsonb().notNull(),
    headers: jsonb().notNull().default({}),
    status: enumText(webhookEventStatuses).notNull().default('received'),
    attempts: integer().notNull().default(0),
    error: text(),
    processedAt: timestamptz(),
  },
  (t) => [uniqueIndex('webhook_events_provider_event_uq').on(t.provider, t.eventId)],
);

/** Keys for other software to call the API. */
export const apiKeys = defineTable(
  'api_keys',
  { module: 'M05', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    /** first 8 characters, shown in lists */
    keyPrefix: text().notNull(),
    keyHash: text().notNull(),
    /** the key can do only these */
    permissionKeys: text().array().notNull(),
    /** empty means all branches */
    branchIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    expiresAt: timestamptz(),
    lastUsedAt: timestamptz(),
    revokedAt: timestamptz(),
  },
  (t) => [uniqueIndex('api_keys_key_hash_uq').on(t.keyHash)],
);

/** Where Takhti sends events to. */
export const webhookEndpoints = defineTable(
  'webhook_endpoints',
  { module: 'M05', scope: 'org' },
  {
    ...baseColumns,
    /** `https` only */
    url: text().notNull(),
    description: text(),
    /** at least one */
    eventNames: text().array().notNull(),
    /** used to sign deliveries */
    secretEncrypted: text().notNull(),
    isActive: boolean().notNull().default(true),
    failureCount: integer().notNull().default(0),
    disabledReason: text(),
  },
  (t) => [
    check('webhook_endpoints_url_https', sql`${t.url} like 'https://%'`),
    check('webhook_endpoints_event_names_some', sql`cardinality(${t.eventNames}) >= 1`),
  ],
);

export const webhookDeliveries = defineTable(
  'webhook_deliveries',
  { module: 'M05', scope: 'org' },
  {
    ...baseColumns,
    endpointId: uuid()
      .references((): AnyPgColumn => webhookEndpoints.id)
      .notNull(),
    eventId: uuid()
      .references((): AnyPgColumn => domainEvents.id)
      .notNull(),
    status: enumText(webhookDeliveryStatuses).notNull().default('pending'),
    attempts: integer().notNull().default(0),
    responseStatus: integer(),
    responseMs: integer(),
    nextAttemptAt: timestamptz(),
    lastError: text(),
  },
  (t) => [
    uniqueIndex('webhook_deliveries_endpoint_event_uq').on(t.endpointId, t.eventId).where(live(t)),
  ],
);

export const biometricDevices = defineTable(
  'biometric_devices',
  { module: 'M05', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    name: text().notNull(),
    serialNo: text().notNull(),
    model: text(),
    location: text(),
    usedFor: enumText(biometricDeviceUsedForOptions).notNull().default('staff'),
    direction: enumText(biometricDeviceDirections).notNull().default('both'),
    lastSeenAt: timestamptz(),
    status: enumText(biometricDeviceStatuses).notNull().default('active'),
  },
  (t) => [uniqueIndex('biometric_devices_serial_no_uq').on(t.orgId, t.serialNo).where(live(t))],
);

/** Maps a person to their number on the machine. */
export const biometricEnrolments = defineTable(
  'biometric_enrolments',
  { module: 'M05', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    personKind: enumText(biometricEnrolmentPersonKinds).notNull(),
    /** required when staff */
    staffId: uuid().references((): AnyPgColumn => staff.id),
    /** required when student */
    studentId: uuid().references((): AnyPgColumn => students.id),
    deviceUserCode: text().notNull(),
  },
  (t) => [
    uniqueIndex('biometric_enrolments_branch_device_user_code_uq')
      .on(t.branchId, t.deviceUserCode)
      .where(live(t)),
    uniqueIndex('biometric_enrolments_branch_staff_uq')
      .on(t.branchId, t.staffId)
      .where(sql`${t.deletedAt} is null and ${t.staffId} is not null`),
    uniqueIndex('biometric_enrolments_branch_student_uq')
      .on(t.branchId, t.studentId)
      .where(sql`${t.deletedAt} is null and ${t.studentId} is not null`),
    check(
      'biometric_enrolments_person',
      sql`(${t.personKind} = 'staff' and ${t.staffId} is not null and ${t.studentId} is null) or (${t.personKind} = 'student' and ${t.studentId} is not null and ${t.staffId} is null)`,
    ),
  ],
);

export const biometricPunches = defineTable(
  'biometric_punches',
  { module: 'M05', scope: 'branch', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    deviceId: uuid()
      .references((): AnyPgColumn => biometricDevices.id)
      .notNull(),
    deviceUserCode: text().notNull(),
    /** the machine's time */
    punchedAt: timestamptz().notNull(),
    direction: enumText(biometricPunchDirections).notNull().default('unknown'),
    /** empty when the code is unknown */
    personKind: enumText(biometricPunchPersonKinds),
    staffId: uuid().references((): AnyPgColumn => staff.id),
    studentId: uuid().references((): AnyPgColumn => students.id),
    isProcessed: boolean().notNull().default(false),
    raw: jsonb().notNull(),
  },
  (t) => [
    uniqueIndex('biometric_punches_device_device_user_code_punched_at_uq').on(
      t.deviceId,
      t.deviceUserCode,
      t.punchedAt,
    ),
    index('biometric_punches_branch_is_processed_punched_at_idx').on(
      t.branchId,
      t.isProcessed,
      t.punchedAt,
    ),
  ],
);
